def event_loop_normal(self):
    while True:
        self.ingest_requests()            # from TokenizerManager (ZMQ)
        batch = self.get_next_batch_to_run()
        if batch:
            result = self.run_batch(batch)        # GPU forward + sample
            self.process_batch_result(batch, result)  # to detokenizer
        self.last_batch = batch

def get_next_batch_to_run(self):
    # 1. finished prefills join the running (decoding) batch
    self.running_batch.merge(self.last_batch_if_prefill())
    # 2. try to build a new prefill batch: sort queue by policy,
    #    admit while tokens fit, chunk a long prompt if needed
    new_batch = self.get_new_batch_prefill()
    if new_batch:
        return new_batch                  # prefill goes first
    # 3. otherwise decode one token for every running request;
    #    if the KV pool is full, retract some back to the queue
    return self.update_running_batch(self.running_batch)
